code.java:
class Solution {
    public int minOperations(int k){
        int value=(int)Math.sqrt(k);
        int copies=(k+value-1)/value;
        return value+copies-2;
    }
}

code.kotlin:
class Solution {
    fun minOperations(k:Int):Int{
        val value=kotlin.math.sqrt(k.toDouble()).toInt();
        val copies=(k+value-1)/value;
        return value+copies-2
    }
}

